// 1. Get the title from the "Create Post Data2" node for the current item
const title = $('Create Post Data2').item.json.title || 'themeparksavvy-post';

// 2. Get the Pexel URL from the "Pexel Image Url" node for the current item
// (Assuming 'Pexel Image Url' is the correct node name)
const pexelUrl = $('Pexel Image Url').item.json['Photo Landscape'];

// 3. Generate the slug
const slug = title
  .toLowerCase()
  .trim()
  .replace(/[^\w\s-]/g, '') // Remove all non-word chars except spaces and hyphens
  .replace(/[\s_-]+/g, '-') // Replace spaces and underscores with a single hyphen
  .replace(/^[-\s]+|[-\s]+$/g, ''); // Remove leading/trailing hyphens

// 4. Return BOTH the new slug AND the Pexel URL
return {
  slug: slug,
  pexel_url_to_download: pexelUrl
}

